type ApiResult={error?:string;state:Workspace;version:number;persisted:boolean;actor?:string};
type Page='grok'|'clients'|'analytics'|'competitors'|'opsweekly'|'opsaudit'|'opsimport'|'studio'|'overview'|'projects'|'weekly'|'decisions'|'research'|'activity'|'sources'|'tasks';
type Modal={kind:string;id?:string;featureId?:string};
const statusText:Record<string,[string,string]>={planned:['Planned','مخطط'],in_progress:['In progress','قيد التنفيذ'],blocked:['Blocked','متعثر'],in_review:['Awaiting evidence','بانتظار الدليل'],completed:['Verified complete','مكتمل بدليل'],needs_review:['Needs review','يحتاج مراجعة'],paused:['Paused','متوقف'],high:['High','عالية'],medium:['Medium','متوسطة'],low:['Low','منخفضة']};
const nav=[['overview',LayoutDashboard,'Overview','نظرة عامة'],['studio',Link2,'Website orders','طلبات الموقع'],['clients',Layers3,'Client delivery','تنفيذ مشاريع العملاء'],['grok',Orbit,'Grok advisor','مستشار Grok'],['analytics',Plug,'Analytics workflows','مسارات التحليل'],['competitors',FlaskConical,'Competitor board','مقارنة المنافسين'],['opsweekly',CalendarDays,'Delivery priorities','أولويات التنفيذ'],['opsaudit',ShieldCheck,'Operations approvals','اعتمادات التشغيل'],['projects',Orbit,'Portfolio projects','محفظة المشاريع'],['weekly',CalendarDays,'Portfolio pulse','تحديث المحفظة'],['decisions',GitBranch,'Decisions','القرارات'],['research',FlaskConical,'Market questions','أسئلة السوق'],['activity',History,'Portfolio history','سجل المحفظة'],['sources',FileText,'Sources & evidence','المصادر والأدلة'],['opsimport',Download,'Previous work','نقل العمل السابق']] as const;
const empty:Workspace={projects:[],tasks:[],decisions:[],updates:[],studies:[],activity:[],sources:[],receipts:[],baselineDate:''};
function values(e:FormEvent<HTMLFormElement>){e.preventDefault();return Object.fromEntries(new FormData(e.currentTarget).entries()) as Record<string,string>}
function upcoming(){const d=new Date();d.setDate(d.getDate()+((7-d.getDay())%7||7));return d.toISOString().slice(0,10)}
function localDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function download(name:string,text:string,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function Field({label,children,wide=false}:{label:string;children:ReactNode;wide?:boolean}){return <label className={'field '+(wide?'wide':'')}><span>{label}</span>{children}</label>}
function Dialog({title,onClose,children,large=false}:{title:string;onClose:()=>void;children:ReactNode;large?:boolean}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{const el=ref.current;el?.showModal();const onCancel=(e:Event)=>{e.preventDefault();onClose()};el?.addEventListener('cancel',onCancel);return()=>el?.removeEventListener('cancel',onCancel)},[onClose]);return <dialog ref={ref} className={'dialog '+(large?'large':'')} onClick={e=>{if(e.target===ref.current)onClose()}}><div className="dialog-head"><h2>{title}</h2><button className="iconbtn" aria-label="Close dialog" onClick={onClose}><X size={20}/></button></div>{children}</dialog>}
export default function Dashboard(){
 const [,setClock]=useState(0);
 const [opsSource,setOpsSource]=useState('');
 const [lang,setLang]=useState<'en'|'ar'>('ar'); const ar=lang==='ar'; const t=(en:string,a:string)=>ar?a:en;
 const [page,setPage]=useState<Page>('overview'),[state,setState]=useState<Workspace>(empty),[version,setVersion]=useState(0),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[error,setError]=useState(''),[auth,setAuth]=useState(false),[toast,setToast]=useState(''),[search,setSearch]=useState(''),[filter,setFilter]=useState('all'),[category,setCategory]=useState('all'),[modal,setModal]=useState<Modal|null>(null),[mobile,setMobile]=useState(false),[persisted,setPersisted]=useState(false),[loaded,setLoaded]=useState(false),[studyDraft,setStudyDraft]=useState(''),[studyOptions,setStudyOptions]=useState({projectId:'project-r',age:'All adults',gender:'Inclusive / neutral',culture:'Saudi Arabia',language:'English',tone:'Friendly'}),[researchTitle,setResearchTitle]=useState('Customer discovery · Round 01'),[recipient,setRecipient]=useState(''),[consent,setConsent]=useState(false);
 const searchRef=useRef<HTMLInputElement>(null);
 const say=(s:string)=>{setToast(s);setTimeout(()=>setToast(''),4200)};
 async function refresh(){setLoading(true);setError('');try{const r=await fetch('/api/core/portfolio',{cache:'no-store'});const d=await r.json() as ApiResult;if(!r.ok){setAuth(r.status===401);throw Error(d.error)}setState(d.state);setVersion(d.version);setPersisted(d.persisted);setAuth(false);setLoaded(true)}catch(e){setError((e as Error).message)}finally{setLoading(false)}}
 useEffect(()=>{const timer=setInterval(()=>setClock(c=>c+1),60000);return()=>clearInterval(timer)},[]);
 useEffect(()=>{refresh();const start=new URLSearchParams(location.search).get('section')||location.hash.slice(1);if(nav.some(n=>n[0]===start))setPage(start as Page);const stored=localStorage.getItem('rowaihy-language');if(stored==='en'||stored==='ar')setLang(stored);const key=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchRef.current?.focus()}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[]);
 useEffect(()=>{document.documentElement.lang=lang;document.documentElement.dir=ar?'rtl':'ltr';localStorage.setItem('rowaihy-language',lang)},[lang,ar]);
 async function mutate(action:string,payload:Record<string,unknown>,close=true){if(saving)return false;setSaving(true);setError('');try{const r=await fetch('/api/core/portfolio',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,payload,version,requestId:crypto.randomUUID()})});const d=await r.json() as ApiResult;if(!r.ok)throw Error(d.error);setState(d.state);setVersion(d.version);setPersisted(true);if(close)setModal(null);say(t('Saved to your workspace','تم الحفظ في مساحة عملك'));return true}catch(e){setError((e as Error).message);return false}finally{setSaving(false)}}
 const projects=state.projects;
 const selected=projects.find(p=>p.id===modal?.id);
 const feature=selected?.features.find(f=>f.id===modal?.featureId);
 const features=projects.flatMap(p=>p.features);
 const verified=features.filter(f=>f.status==='completed'&&f.evidence);
 const evidenceNeeded=features.filter(f=>f.status==='in_review');
 const openDecisions=state.decisions.filter(d=>d.status==='open');
 const today=localDate();
 const dueTasks=state.tasks.filter(x=>!x.done&&x.due<=new Date(Date.now()+7*86400000).toISOString().slice(0,10));
 const overdueProjects=projects.filter(p=>p.status!=='completed'&&p.due&&p.due<=new Date(Date.now()+7*86400000).toISOString().slice(0,10));
 const alertCount=dueTasks.length+overdueProjects.length;
 const filtered=projects.filter(p=>(p.name+' '+p.description).toLowerCase().includes(search.toLowerCase())&&(category==='all'||p.category===category)&&(filter==='all'||(filter==='attention'?(p.status==='needs_review'||p.status==='blocked'||!!p.blocker):p.status===filter)));
 const badge=(status:string)=><span className={'badge '+status}><span/>{statusText[status]?.[ar?1:0]??status}</span>;
 const icon=(p:Project)=><span className="project-icon" style={{color:p.color,background:p.color+'14',borderColor:p.color+'30'}}>{p.initials}</span>;
 const projectSelect=(name='projectId',id?:string)=><select name={name} defaultValue={id??projects[0]?.id} required>{projects.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select>;
 const formFooter=(label=t('Save changes','حفظ التغييرات'))=><div className="form-footer"><button type="button" className="btn ghost" onClick={()=>setModal(null)}>{t('Cancel','إلغاء')}</button><button className="btn primary" disabled={saving}>{saving?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>} {label}</button></div>;
 function exportWorkspace(){download('ROWAIHY_MIND_workspace.json',JSON.stringify({exportedAt:new Date().toISOString(),version,...state},null,2),'application/json');say(t('Workspace exported','تم تصدير مساحة العمل'))}
 function calendarExport(){const esc=(s:string)=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const events=[...state.tasks.filter(x=>!x.done).map(x=>({id:x.id,title:x.title,date:x.due})),...projects.filter(x=>x.due).map(x=>({id:x.id,title:x.name,date:x.due}))];if(!events.length){say(t('Add a dated task or project first.','أضف مهمة أو مشروعًا بتاريخ أولًا.'));return}download('ROWAIHY_MIND_deadlines.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ROWAIHY MIND//EN',...events.flatMap(x=>['BEGIN:VEVENT',`UID:${x.id}@rowaihy-mind`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${x.date.replace(/-/g,'')}`,`SUMMARY:${esc(x.title)}`,'BEGIN:VALARM','TRIGGER:-P1D','ACTION:DISPLAY',`DESCRIPTION:${esc(x.title)}`,'END:VALARM','END:VEVENT']),'END:VCALENDAR'].join('\r\n'),'text/calendar')}
 const close=()=>setModal(null);
 const currentNav=nav.find(n=>n[0]===page);
 const isDelivery=['grok','studio','clients','analytics','competitors','opsweekly','opsaudit','opsimport'].includes(page);
 useEffect(()=>{const u=new URL(location.href);u.searchParams.set('section',page);u.hash='';history.replaceState(null,'',u);},[page]);
 return <div className="app-shell" dir={ar?'rtl':'ltr'}>
 <aside className={'sidebar '+(mobile?'show':'')}>
  <a href="#" className="brand" onClick={e=>{e.preventDefault();setPage('overview')}}><img src="/assets/rowaihy-mark.png" alt="ROWAIHY MIND"/><span>PROJECT <b>R</b><small>STUDIO · FOUNDER WORKSPACE</small></span></a>
  <div className="workspace-switch"><span className="mini-r">R</span><div>ROWAIHY MIND Core<small>{t('Private management','إدارة خاصة')}</small></div><Lock size={13}/></div>
  <div className="nav-label">{t('WORKSPACE','مساحة العمل')}</div>
  <a className="core-portal-link" href="/studio.html">{t('Client portal','بوابة العملاء')}<ArrowUpRight size={14}/></a><nav>{nav.map(([id,Icon,en,a])=><button key={id} className={page===id?'active':''} onClick={()=>{setPage(id);setSearch('');setMobile(false)}}><Icon size={18}/><span>{t(en,a)}</span>{id==='decisions'&&openDecisions.length>0&&<em>{openDecisions.length}</em>}{id==='overview'&&<i/>}</button>)}</nav>
  <div className="sidebar-bottom"><div className="evidence-card"><ShieldCheck size={23}/><strong>{t('Progress needs proof.','الإنجاز يحتاج دليلًا.')}</strong><p>{t('Every completed feature has a source and a human review.','كل ميزة مكتملة لها مصدر ومراجعة بشرية.')}</p><button onClick={()=>setPage('sources')}>{t('Our evidence standard','معيار توثيق الإنجاز')} <ArrowUpRight size={14}/></button></div><div className="studio-mark">PROJEC<span>T</span> R <b>STUDIO</b></div><div className="profile"><div className="avatar">AR</div><div><strong>ABO7MEED</strong><small>{t('Founder · Private workspace','المؤسس · مساحة خاصة')}</small></div><ShieldCheck size={16}/></div></div>
 </aside>
 {mobile&&<button className="sidebar-shade" aria-label="Close navigation" onClick={()=>setMobile(false)}/>}
 <div className="main-shell">
 <header className="topbar"><div className="breadcrumb"><button className="iconbtn mobile-menu" onClick={()=>setMobile(!mobile)} aria-label="Open navigation"><Menu size={20}/></button><span>Workspace</span><ChevronRight size={14}/><strong>{currentNav?t(currentNav[2],currentNav[3]):t('Tasks & alerts','المهام والتنبيهات')}</strong></div><div className="top-actions"><div className="global-search"><Search size={16}/><input ref={searchRef} placeholder={t('Find a project…','ابحث عن مشروع…')} value={search} onChange={e=>{setSearch(e.target.value);if(page!=='overview'&&page!=='projects')setPage('projects')}} aria-label="Search projects"/><kbd>⌘ K</kbd></div><button className="language" onClick={()=>setLang(ar?'en':'ar')}><Globe2 size={15}/>{ar?'EN':'العربية'}</button><span className="top-divider"/><button className="iconbtn notification" aria-label={t('Open deadline alerts','فتح تنبيهات المواعيد')} onClick={()=>setPage('tasks')}><Bell size={19}/>{alertCount>0&&<b>{alertCount}</b>}</button><div className="avatar small">AR</div></div></header>
 <main>
 <div className="page-heading"><div><div className="eyebrow"><span/>{t('YOUR IDEAS. A CLEARER DIRECTION.','أفكارك. برؤية أوضح.')}</div><h1>{page==='overview'?t('Portfolio overview','نظرة عامة على المشاريع'):currentNav?t(currentNav[2],currentNav[3]):t('Tasks & alerts','المهام والتنبيهات')}</h1><p>{page==='overview'?t('Every project, every decision, every next move.','كل مشروع، وكل قرار، وكل خطوة قادمة.'):page==='research'?t('Better questions. Honest signals. Build what people need.','أسئلة أفضل وإشارات صادقة لبناء ما يحتاجه العملاء.'):page==='sources'?t('Know what is verified, what is claimed, and what is still a plan.','اعرف ما تم التحقق منه وما أُبلغ عنه وما يزال مخططًا.'):t('A focused view of the work that matters.','متابعة مركزة للعمل الذي يهمك.')}</p></div>{!isDelivery&&<div className="heading-actions"><button className="btn" onClick={()=>setModal({kind:'weekly'})} disabled={!loaded}><CalendarDays size={16}/>{t('Weekly update','تحديث أسبوعي')}</button><button className="btn primary" onClick={()=>setModal({kind:'new'})} disabled={!loaded}><Plus size={17}/>{t('New project','مشروع جديد')}</button></div>}</div>
 {error&&<div className="error-box" role="alert"><TriangleAlert size={18}/><span>{error}</span>{auth?<a href="/signin-with-chatgpt?return_to=%2Fadmin" target="_top">{t('Sign in','تسجيل الدخول')}</a>:<button onClick={refresh}>{t('Refresh','تحديث')}</button>}</div>}
 {page==='grok'&&<GrokAdvisor ar={ar}/>}
 {page==='studio'&&<StudioLive ar={ar} onManage={id=>{setOpsSource(id);setPage('clients')}}/>}
 {['clients','analytics','competitors','opsweekly','opsaudit','opsimport'].includes(page)&&<OperationsPanel ar={ar} view={page} sourceId={opsSource}/>}
 {loading&&!loaded?<div className="loading"><Orbit className="spin" size={34}/><p>{t('Opening your private workspace…','جارٍ فتح مساحة عملك الخاصة…')}</p></div>:loaded&&<>
 {page==='overview'&&<div className="studio-entry"><div><strong>PROJECT R STUDIO · ROWAIHY MIND Core</strong><p>{t('Website requests and delivery, automatically in view.','طلبات الموقع ومراحل التسليم، تظهر تلقائيًا أمامك.')}</p></div><button className="btn" onClick={()=>setPage('studio')}>{t('Open website orders','فتح طلبات الموقع')}<ArrowUpRight size={16}/></button></div>}
 {(page==='overview'||page==='projects')&&<>
 {page==='overview'&&<><section className="hero"><div className="hero-content"><div className="hero-kicker"><span className="live-dot"/>{t('FOUNDER COMMAND CENTER','مركز قيادة المؤسس')}<span className="hero-rule"/><span>01 / MIND</span></div><h2>{t('Build with intent.','ابنِ بهدف.')}<br/><span>{t('Move with evidence.','وتقدّم بدليل.')}</span></h2><p>{t('Turn a portfolio of possibilities into a week of meaningful progress.','حوّل إمكانات مشاريعك إلى أسبوع من التقدم الملموس.')}</p><button onClick={()=>setPage('weekly')}>{t('Plan your next week','خطط لأسبوعك القادم')}<ArrowUpRight size={16}/></button></div><div className="core-scene" aria-hidden="true"><div className="orb-halo"/><div className="orbit one"/><div className="orbit two"/><div className="orbit three"/><div className="core"><img src="/assets/rowaihy-mark.png" alt=""/></div><div className="core-tag"><i/>ROWAIHY INTELLIGENCE CORE</div><span className="coord">25.285° N<br/>BUILD / VALIDATE / EVOLVE</span></div><div className="hero-foot"><ShieldCheck size={13}/>{t('One platform · Client portal & private management','منصة واحدة · بوابة عملاء وإدارة خاصة')}</div></section>
 <div className="metrics"><Metric icon={<Layers3 size={19}/>} label={t('Projects tracked','مشاريع قيد المتابعة')} value={projects.length} note={t('Across your digital portfolio','ضمن محفظتك الرقمية')} color="violet"/><Metric icon={<ShieldCheck size={19}/>} label={t('Verified features','ميزات مكتملة بدليل')} value={verified.length} note={`${t('of','من')} ${features.length} ${t('tracked features','ميزة متتبعة')}`} color="green"/><Metric icon={<Clock size={19}/>} label={t('Awaiting evidence','بانتظار الدليل')} value={evidenceNeeded.length} note={t('Reported work, pending review','أعمال مُبلّغ عنها تنتظر التحقق')} color="amber"/><Metric icon={<GitBranch size={19}/>} label={t('Open decisions','قرارات مفتوحة')} value={openDecisions.length} note={t('Your direction is needed','تحتاج إلى توجيهك')} color="blue"/></div></>}
 <div className={page==='overview'?'dashboard-grid':''}><section className="panel projects-panel"><div className="panel-head"><div><h3>{t('Your portfolio','محفظة مشاريعك')} <span className="count">{projects.length}</span></h3><p>{t('A clear line between ambition and delivery.','فصل واضح بين الطموح والتنفيذ.')}</p></div><button className="text-btn" onClick={exportWorkspace}><Download size={15}/>{t('Export','تصدير')}</button></div><div className="filters"><div className="tabs">{[['all','All projects','كل المشاريع'],['in_progress','In progress','قيد التنفيذ'],['attention','Needs attention','تحتاج اهتمامًا'],['planned','Planned','مخطط']].map(([id,en,a])=><button key={id} className={filter===id?'selected':''} onClick={()=>setFilter(id)}>{t(en,a)}</button>)}</div><label className="category"><SlidersHorizontal size={14}/><select value={category} onChange={e=>setCategory(e.target.value)} aria-label="Project category"><option value="all">{t('All categories','كل الفئات')}</option>{['AI & Products','SportsTech','Hospitality','Commerce'].map(c=><option key={c}>{c}</option>)}</select></label></div>
 <div className="table-wrap"><table className="projects-table"><thead><tr><th>{t('PROJECT','المشروع')}</th><th>{t('STATUS','الحالة')}</th><th>{t('VERIFIED DELIVERY','إنجاز موثق')}</th><th>{t('PRIORITY','الأولوية')}</th><th/></tr></thead><tbody>{filtered.slice(0,page==='overview'?7:150).map(p=>{const done=p.features.filter(f=>f.status==='completed'&&f.evidence).length;return <tr key={p.id} onClick={()=>setModal({kind:'project',id:p.id})}><td><button className="project-name" onClick={e=>{e.stopPropagation();setModal({kind:'project',id:p.id})}}>{icon(p)}<span><strong>{p.name}</strong><small>{p.category}</small></span></button></td><td>{badge(p.status)}</td><td><div className="delivery"><div className="progress"><i style={{width:`${p.features.length?done/p.features.length*100:0}%`}}/></div><span>{done}<em> / {p.features.length}</em></span></div></td><td><span className={'priority '+p.priorityLevel}><i/><i/><i/>{statusText[p.priorityLevel]?.[ar?1:0]}</span></td><td><ChevronRight size={16}/></td></tr>})}</tbody></table>{!filtered.length&&<Empty icon={<Search/>} title={t('No projects found','لم يتم العثور على مشاريع')} text={t('Try a different search or filter.','جرّب بحثًا أو فلترًا مختلفًا.')}/>}</div><div className="table-foot"><span><ShieldCheck size={13}/>{t('Completion requires linked evidence + human review','الاكتمال يتطلب دليلًا مرتبطًا + مراجعة بشرية')}</span>{page==='overview'&&<button onClick={()=>setPage('projects')}>{t('View all projects','عرض كل المشاريع')}<ArrowRight size={14}/></button>}</div></section>
 {page==='overview'&&<aside className="right-rail"><section className="panel priorities"><div className="panel-head"><h3><Target size={17}/>{t('Next week’s focus','تركيز الأسبوع القادم')}</h3><span className="micro">{t('PROPOSED','مقترح')}</span></div><p className="rail-sub">{t('Three moves to unlock momentum.','ثلاث خطوات لدفع العمل للأمام.')}</p>{projects.filter(p=>p.priorityLevel==='high').slice(0,3).map((p,i)=><button className="focus-item" key={p.id} onClick={()=>setModal({kind:'project',id:p.id})}><span className="focus-number">0{i+1}</span><div><small>{p.name}</small><p>{p.priority}</p></div><ArrowUpRight size={14}/></button>)}<button className="rail-link" onClick={()=>setPage('weekly')}>{t('Open weekly plan','فتح الخطة الأسبوعية')}<ArrowRight size={15}/></button></section><section className="panel decision-panel"><div className="panel-head"><h3><GitBranch size={17}/>{t('Your call','قرارك مطلوب')}</h3><span className="count amber-text">{openDecisions.length}</span></div>{openDecisions.slice(0,2).map(d=><button className="decision-mini" key={d.id} onClick={()=>setModal({kind:'decision',id:d.id})}><small>{projects.find(p=>p.id===d.projectId)?.name}</small><p>{d.title}</p><span>{t('Review decision','مراجعة القرار')}<ArrowUpRight size={13}/></span></button>)}</section></aside>}</div>
 </>}
 {page==='weekly'&&<><section className="weekly-banner"><div><div className="eyebrow">{t('REFLECT → PRIORITIZE → BUILD','راجع ← رتّب الأولويات ← ابنِ')}</div><h2>{t('Make the next seven days count.','اجعل الأيام السبعة القادمة مؤثرة.')}</h2><p>{t('Record progress, surface friction and commit to one clear next move.','سجل التقدم والعوائق وحدد خطوة قادمة واضحة.')}</p></div><button className="btn primary" onClick={()=>setModal({kind:'weekly'})}><Plus size={16}/>{t('Write an update','كتابة تحديث')}</button></section><div className="two-col"><section className="panel"><div className="panel-head"><h3>{t('Weekly updates','التحديثات الأسبوعية')}</h3><span className="count">{state.updates.length}</span></div>{state.updates.length?state.updates.map(u=><article className="update-card" key={u.id}><small>{u.week} · {projects.find(p=>p.id===u.projectId)?.name}</small><h4>{u.priority}</h4><p>{u.wins||t('No progress reported','لم يُبلغ عن تقدم')}</p><dl><dt>{t('Next','القادم')}</dt><dd>{u.planned}</dd><dt>{t('Blockers','العوائق')}</dt><dd>{u.blocker||'—'}</dd><dt>{t('Weaknesses','نقاط الضعف')}</dt><dd>{u.weakness||'—'}</dd><dt>{t('Decisions','القرارات')}</dt><dd>{u.decision||'—'}</dd><dt>{t('Evidence notes','ملاحظات الأدلة')}</dt><dd>{u.evidence||'—'}</dd></dl><span className="small-note">{t('Reported progress · feature statuses remain independently verified','تقدم مُبلّغ عنه · التحقق من الميزات مستقل')}</span></article>):<Empty icon={<CalendarDays/>} title={t('Your first weekly pulse','أول تحديث أسبوعي لك')} text={t('No updates submitted yet. Start with what changed, what is blocked and what comes next.','لم تُرسل تحديثات بعد. ابدأ بما تغير وما تعثر وما سيأتي.')}/>}</section><section className="panel"><div className="panel-head"><h3>{t('Priority queue','قائمة الأولويات')}</h3><span className="micro">{t('OWNER EDITABLE','قابلة للتعديل')}</span></div>{[...projects].sort((a,b)=>['high','medium','low'].indexOf(a.priorityLevel)-['high','medium','low'].indexOf(b.priorityLevel)).map((p,i)=><button className="focus-item" key={p.id} onClick={()=>setModal({kind:'editProject',id:p.id})}><span className="focus-number">{String(i+1).padStart(2,'0')}</span><div><small>{p.name}</small><p>{p.priority}</p></div><Flag size={14}/></button>)}</section></div></>}
 {page==='decisions'&&<section className="panel"><div className="panel-head"><div><h3>{t('Decisions move work forward','القرارات تدفع العمل للأمام')}</h3><p>{t('Founder decisions are recorded with author and timestamp.','تُسجل قرارات المؤسس بالاسم والتاريخ.')}</p></div><button className="btn" onClick={()=>setModal({kind:'newDecision'})}><Plus size={16}/>{t('Add decision','إضافة قرار')}</button></div><div className="decision-grid">{state.decisions.map(d=><article className="decision-card" key={d.id}><div><span className={'badge '+(d.status==='open'?'in_review':'completed')}>{d.status==='open'?t('Decision needed','قرار مطلوب'):t('Resolved','تم اتخاذ القرار')}</span><small>{projects.find(p=>p.id===d.projectId)?.name}</small></div><h3>{d.title}</h3><p>{d.context}</p>{d.answer?<div className="decision-answer"><CheckCircle2 size={16}/><span>{d.answer}<small>{d.decidedBy} · {d.decidedAt?.slice(0,10)}</small></span></div>:<button className="text-btn violet-text" onClick={()=>setModal({kind:'decision',id:d.id})}>{t('Make a decision','اتخاذ قرار')}<ArrowUpRight size={15}/></button>}</article>)}</div></section>}
 {page==='research'&&<><div className="two-col research-grid"><section className="panel research-form"><div className="panel-head"><h3><FlaskConical size={18}/>{t('Question studio','استوديو الأسئلة')}</h3><span className="micro">{t('GUIDED TEMPLATES','قوالب موجهة')}</span></div><div className="form-body"><Field label={t('Study name','اسم الدراسة')}><input value={researchTitle} onChange={e=>setResearchTitle(e.target.value)} maxLength={150}/></Field><Field label={t('Project','المشروع')}><select value={studyOptions.projectId} onChange={e=>{setStudyOptions({...studyOptions,projectId:e.target.value});setStudyDraft('')}}>{projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><div className="form-grid">{([['age',t('Age range','الفئة العمرية'),['All adults','18–24','25–44','45–64','65+','Under 18']],['gender',t('Address preference','صيغة الخطاب'),['Inclusive / neutral','Feminine address','Masculine address']],['culture',t('Cultural context','السياق الثقافي'),['Saudi Arabia','Gulf / GCC','International']],['language',t('Question language','لغة الأسئلة'),['English','Arabic']],['tone',t('Tone of voice','أسلوب الخطاب'),['Friendly','Professional','Simple']]] as [keyof typeof studyOptions,string,string[]][]).map(([k,label,opts])=><Field key={k} label={label}><select value={studyOptions[k]} onChange={e=>{setStudyOptions({...studyOptions,[k]:e.target.value});setStudyDraft('')}}>{opts.map(o=><option key={o}>{o}</option>)}</select></Field>)}</div><div className="note"><ShieldCheck size={16}/><p>{t('Preferences are chosen, never inferred. Gender changes address only; age and culture never stand in for needs or ability.','التفضيلات تُختار ولا تُستنتج. الجنس يغير صيغة الخطاب فقط، والعمر والثقافة لا يحددان احتياجات الشخص أو قدراته.')}</p></div>{studyOptions.age==='Under 18'&&<div className="warning">{t('Guardian review and permission are required before contacting minors. Do not request sensitive information.','تُطلب مراجعة ولي الأمر وموافقته قبل التواصل مع القاصرين. لا تطلب معلومات حساسة.')}</div>}<button className="btn primary full" onClick={()=>setStudyDraft(buildQuestions({...studyOptions,project:projects.find(p=>p.id===studyOptions.projectId)?.name??''}))}><FlaskConical size={16}/>{t('Prepare questions','إعداد الأسئلة')}</button></div></section><section className="panel question-preview"><div className="panel-head"><h3>{t('Review before sharing','راجع قبل المشاركة')}</h3><span className="badge planned">{t('Draft','مسودة')}</span></div>{studyDraft?<div className="form-body"><textarea className="question-editor" value={studyDraft} onChange={e=>setStudyDraft(e.target.value)} dir={studyOptions.language==='Arabic'?'rtl':'ltr'} aria-label="Edit customer questions" maxLength={12000}/><p className="small-note">{t('Editable template · no customer message has been sent.','قالب قابل للتعديل · لم تُرسل أي رسالة للعميل.')}</p><div className="button-row"><button className="btn primary" disabled={saving} onClick={()=>mutate('saveStudy',{...studyOptions,title:researchTitle,questions:studyDraft},false)}><Check size={16}/>{t('Save draft','حفظ المسودة')}</button><button className="btn" onClick={async()=>{try{await navigator.clipboard.writeText(studyDraft);say(t('Questions copied','تم نسخ الأسئلة'))}catch{say(t('Use the editable text to copy manually.','انسخ النص من مربع التحرير.'))}}}><Copy size={16}/>{t('Copy','نسخ')}</button></div><div className="share-section"><Field label={t('Customer email','بريد العميل')}><input type="email" placeholder="customer@example.com" value={recipient} onChange={e=>setRecipient(e.target.value)}/></Field><label className="checkbox"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>{t('I reviewed the questions and have permission to contact this recipient.','راجعت الأسئلة ولدي موافقة على التواصل مع هذا المستلم.')}</span></label><button className="btn full" disabled={!consent||!/^\S+@\S+\.\S+$/.test(recipient)} onClick={()=>{window.location.href=`mailto:${encodeURIComponent(recipient)}?subject=${encodeURIComponent(researchTitle)}&body=${encodeURIComponent(studyDraft)}`}}><Send size={15}/>{t('Open email draft','فتح مسودة البريد')}</button><small>{t('Your email app handles delivery. This workspace does not track sending or responses.','تطبيق البريد يتولى الإرسال. لا تتبع هذه المساحة الإرسال أو الردود.')}</small></div></div>:<Empty icon={<FileText size={32}/>} title={t('A thoughtful conversation starts here','محادثة مدروسة تبدأ هنا')} text={t('Choose a project and audience preferences, then prepare your editable question set.','اختر المشروع وتفضيلات الجمهور، ثم جهّز أسئلة قابلة للتحرير.')}/>}</section></div><section className="panel saved-studies"><div className="panel-head"><h3>{t('Saved research drafts','مسودات البحث المحفوظة')}</h3><span className="count">{state.studies.length}</span></div>{state.studies.length?state.studies.map(s=><button className="study-row" key={s.id} onClick={()=>setModal({kind:'study',id:s.id})}><FlaskConical size={19}/><span><strong>{s.title}</strong><small>{projects.find(p=>p.id===s.projectId)?.name} · {s.language} · {s.createdAt.slice(0,10)}</small></span><span className="badge planned">{t('Draft','مسودة')}</span><ArrowUpRight size={15}/></button>):<p className="empty-inline">{t('Saved question sets will appear here.','ستظهر مجموعات الأسئلة المحفوظة هنا.')}</p>}</section></>}
 {page==='activity'&&<section className="panel"><div className="panel-head"><div><h3>{t('An accountable trail','سجل للمساءلة')}</h3><p>{t('Every saved change has an actor, timestamp and record. Initial source references are not delivery events.','لكل تغيير محفوظ اسم وتاريخ وسجل. المراجع الأولية ليست أحداث إنجاز.')}</p></div><button className="btn" onClick={exportWorkspace}><Download size={16}/>{t('Export log','تصدير السجل')}</button></div>{state.activity.length?<div className="timeline">{state.activity.map(a=><article key={a.id}><span className="timeline-dot"><Activity size={14}/></span><div><strong>{actionLabel(a.action,ar)}</strong><p>{a.detail}</p><small>{a.actor} · {new Date(a.at).toLocaleString(ar?'ar-SA':'en-GB',{timeZone:'Asia/Riyadh',dateStyle:'medium',timeStyle:'short'})} AST</small></div></article>)}</div>:<Empty icon={<History/>} title={t('A clean starting point','بداية واضحة')} text={t('Your first saved update will start the activity trail. No historical completion has been invented.','سيبدأ السجل مع أول تحديث محفوظ. لم يُفترض أي إنجاز تاريخي.')}/>}</section>}
 {page==='sources'&&<><section className="evidence-standard"><ShieldCheck size={35}/><div><h2>{t('Evidence is the standard.','الدليل هو المعيار.')}</h2><p>{t('Planned → In progress → Awaiting evidence → Verified complete. A source link alone does not prove a working feature.','مخطط ← قيد التنفيذ ← بانتظار الدليل ← مكتمل بدليل. الرابط وحده لا يثبت أن الميزة تعمل.')}</p><div className="standard-tags"><span><Link2 size={14}/>{t('Relevant evidence link','رابط دليل ذي صلة')}</span><span><CheckSquare size={14}/>{t('Test outcome','نتيجة تحقق')}</span><span><ShieldCheck size={14}/>{t('Named human reviewer','مراجع بشري معروف')}</span></div></div></section><div className="source-notice"><Plug size={19}/><div><strong>{t('Live app sync is not enabled','المزامنة الحية للتطبيقات غير مفعلة')}</strong><p>{t('These are dated source-review notes, not live connections. Sites connector eligibility could not be checked in this environment. Refresh reloads saved workspace data only.','هذه ملاحظات مراجعة مؤرخة وليست اتصالات حية. تعذر التحقق من إتاحة ربط التطبيقات داخل Sites. زر التحديث يعيد تحميل بيانات مساحة العمل المحفوظة فقط.')}</p></div></div><div className="sources-grid">{state.sources.map((s,i)=><article className="panel source-card" key={s.name}><div><span className="source-symbol">{s.name.slice(0,1)}</span><span className={'badge '+(s.status==='reviewed'?'in_review':'planned')}>{s.status==='reviewed'?t('Reference reviewed','مرجع تمت مراجعته'):s.status==='empty'?t('No projects returned','لم تُرجع مشاريع'):t('Limited coverage','تغطية محدودة')}</span></div><h3>{s.name}</h3><p>{s.description}</p>{s.url?<a href={s.url} target="_blank" rel="noreferrer">{t('Open source','فتح المصدر')}<ArrowUpRight size={14}/></a>:<small>{t('No verified source selected','لم يُحدد مصدر موثق')}</small>}</article>)}</div><div className="source-foot"><strong>{t('Baseline: 07 Nov 2026','الخط الأساس: 7 نوفمبر 2026')}</strong><p>{t('16 initial project tracks were assembled from reviewed references and prior scope. Conversation-only entries are explicitly labeled and remain unverified. Add missing projects or attach fresh proof at any time.','جُمعت 16 مساحة مشروع من المراجع التي تمت مراجعتها والنطاق السابق. السجلات المستندة إلى المحادثات موسومة وغير متحقق منها. يمكنك إضافة المشاريع الناقصة والأدلة الجديدة.')}</p></div></>}
 {page==='tasks'&&<section className="panel"><div className="panel-head"><div><h3>{t('Deadlines, without the guesswork','مواعيد تحددها بنفسك')}</h3><p>{t('Alerts update while the site is open. Import the calendar file for reminders outside the site.','تتحدث التنبيهات أثناء فتح الموقع. استورد ملف التقويم للتذكير خارج الموقع.')}</p></div><div className="button-row"><button className="btn" onClick={calendarExport}><Download size={15}/>{t('Calendar export','تصدير التقويم')}</button><button className="btn primary" onClick={()=>setModal({kind:'task'})}><Plus size={16}/>{t('Add task','إضافة مهمة')}</button></div></div>{state.tasks.length||projects.some(p=>p.due)?<div className="task-list">{state.tasks.map(task=><div className={'task-row '+(task.done?'done':'')} key={task.id}><button className="check-task" disabled={saving} aria-label={(task.done?'Reopen ':'Complete ')+task.title} onClick={()=>mutate('taskStatus',{id:task.id,done:!task.done},false)}>{task.done&&<Check size={15}/>}</button><div><strong>{task.title}</strong><small>{projects.find(p=>p.id===task.projectId)?.name}</small></div><span className={task.due<today&&!task.done?'overdue':''}>{task.due}{task.due<today&&!task.done&&' · '+t('Overdue','متأخرة')}</span>{badge(task.priority)}</div>)}{projects.filter(p=>p.due).map(p=><div className="task-row" key={p.id}><CalendarDays size={18}/><div><strong>{p.name}</strong><small>{t('Project milestone','موعد المشروع')}</small></div><span className={p.due<today?'overdue':''}>{p.due}</span><button className="text-btn" onClick={()=>setModal({kind:'editProject',id:p.id})}>{t('Edit','تعديل')}</button></div>)}</div>:<Empty icon={<Bell/>} title={t('No deadlines assumed','لم نفترض أي مواعيد')} text={t('Add your first dated task. Near-term and overdue items will appear here and in the notification badge.','أضف أول مهمة بتاريخ. ستظهر المهام القريبة والمتأخرة هنا وفي شارة التنبيهات.')}/>}</section>}
 <footer className="main-footer"><span><Lock size={12}/>{t('Private workspace','مساحة عمل خاصة')}<i/> {isDelivery?t('PROJECT R STUDIO Operations','عمليات PROJECT R STUDIO'):persisted?t('Saved workspace','مساحة محفوظة'):t('Reviewed baseline · save a change to initialize','خط أساس تمت مراجعته · احفظ تغييرًا لبدء السجل')}</span>{!isDelivery&&<button onClick={refresh} disabled={loading}><RefreshCw size={13} className={loading?'spin':''}/>{t('Refresh workspace','تحديث مساحة العمل')}</button>}<span>ROWAIHY MIND <span className="muted">/</span> PROJECT R STUDIO</span></footer>
 </>}
 </main></div>
 {toast&&<div className="toast" role="status"><CheckCircle2 size={17}/>{toast}</div>}
 {modal&&<Dialog title={modal.kind==='project'?(selected?.name??''):modal.kind==='new'?t('Create a project','إنشاء مشروع'):modal.kind==='weekly'?t('Your weekly update','تحديثك الأسبوعي'):modal.kind==='verify'?t('Review feature evidence','مراجعة دليل الميزة'):modal.kind==='editProject'?t('Project direction','توجيه المشروع'):modal.kind==='task'?t('Add a dated task','إضافة مهمة بتاريخ'):modal.kind==='decision'?t('Record your decision','تسجيل قرارك'):modal.kind==='newDecision'?t('A decision to make','قرار مطلوب'):t('Research draft','مسودة البحث')} onClose={close} large={modal.kind==='project'||modal.kind==='weekly'}>
 {error&&<div className="error-box" role="alert">{error}</div>}
 {modal.kind==='project'&&selected&&<div className="project-detail"><div className="detail-intro">{icon(selected)}<div><p>{ar&&selected.descriptionAr?selected.descriptionAr:selected.description}</p><div className="button-row">{badge(selected.status)}<span className="small-note">{selected.category}</span></div></div><button className="btn" onClick={()=>setModal({kind:'editProject',id:selected.id})}>{t('Edit direction','تعديل التوجيه')}</button></div><div className="source-reference"><Link2 size={15}/><div>{selected.source?<a href={selected.source} target="_blank" rel="noreferrer">{selected.sourceLabel}<ExternalLink size={12}/></a>:<span>{t('Prior conversation scope — not re-audited','نطاق من محادثة سابقة — لم تُراجع النسخة الحالية')}</span>}<small>{selected.basis}</small></div></div><h3 className="section-label">{t('Feature delivery','تنفيذ الميزات')}<span className="micro">{t('PROOF BEFORE COMPLETE','الدليل قبل الاكتمال')}</span></h3>{selected.features.length?selected.features.map(f=><div className="feature-row" key={f.id}><div className={'feature-marker '+f.status}>{f.status==='completed'?<Check size={15}/>:f.status==='in_review'?<Clock size={15}/>:<span/>}</div><div><strong>{ar&&f.titleAr?f.titleAr:f.title}</strong>{f.evidence&&<small><a target="_blank" rel="noreferrer" href={f.evidence.url}>{t('View evidence','عرض الدليل')} ↗</a> · {f.evidence.reviewer} · {f.evidence.reviewedAt.slice(0,10)}</small>}{f.evidence&&<small>{f.evidence.summary} · {f.evidence.result}</small>}</div>{badge(f.status)}<button className="text-btn" onClick={()=>setModal({kind:'verify',id:selected.id,featureId:f.id})}>{t('Review','مراجعة')}<ChevronRight size={14}/></button></div>):<p className="empty-inline">{t('Add the first planned feature.','أضف أول ميزة مخططة.')}</p>}<form className="inline-form" onSubmit={e=>{const v=values(e);mutate('addFeature',{projectId:selected.id,title:v.title},false).then(ok=>{if(ok)(document.getElementById('feature-title') as HTMLInputElement).value=''})}}><input id="feature-title" name="title" placeholder={t('Add a planned feature…','أضف ميزة مخططة…')} aria-label="New feature title" required maxLength={200}/><button className="btn" disabled={saving}><Plus size={15}/>{t('Add','إضافة')}</button></form><div className="risk-grid">{[[TriangleAlert,t('Weakness','نقطة الضعف'),selected.weakness],[Flag,t('Blocker','العائق'),selected.blocker],[Target,t('Next priority','الأولوية القادمة'),selected.priority]].map(([Icon,label,txt],i)=>{const I=Icon as typeof Flag;return <div key={i}><h4><I size={16}/>{label as string}</h4><p>{txt as string||t('Not recorded','لم يُسجل')}</p></div>})}</div><div className="detail-footer"><span>{t('Owner','المسؤول')}: {selected.owner} · {selected.due||t('No deadline set','لم يحدد موعد')}</span><button className="btn primary" onClick={()=>setModal({kind:'weekly',id:selected.id})}>{t('Write weekly update','كتابة تحديث أسبوعي')}<ArrowRight size={15}/></button></div></div>}
 {modal.kind==='new'&&<form onSubmit={e=>mutate('createProject',values(e))}><div className="form-grid"><Field label={t('Project name','اسم المشروع')} wide><input name="name" required maxLength={100} placeholder="Your next big idea"/></Field><Field label={t('Category','الفئة')}><select name="category">{['AI & Products','SportsTech','Hospitality','Commerce','Other'].map(c=><option key={c}>{c}</option>)}</select></Field><Field label={t('Owner','المسؤول')}><input name="owner" defaultValue="ABO7MEED" required maxLength={100}/></Field><Field label={t('What does it do?','ما وظيفة المشروع؟')} wide><textarea name="description" required maxLength={500}/></Field><Field label={t('Next priority','الأولوية القادمة')} wide><textarea name="priority" required maxLength={500}/></Field><Field label={t('Priority level','درجة الأولوية')}><select name="priorityLevel"><option value="medium">{t('Medium','متوسطة')}</option><option value="high">{t('High','عالية')}</option><option value="low">{t('Low','منخفضة')}</option></select></Field><Field label={t('Target date (optional)','الموعد المستهدف (اختياري)')}><input type="date" name="due"/></Field></div><div className="note"><ShieldCheck size={16}/><p>{t('New projects start as Planned, with no assumed achievements.','تبدأ المشاريع الجديدة كمخططة دون افتراض أي إنجازات.')}</p></div>{formFooter(t('Create project','إنشاء مشروع'))}</form>}
 {modal.kind==='editProject'&&selected&&<form onSubmit={e=>mutate('projectUpdate',{...values(e),projectId:selected.id,attest:(new FormData(e.currentTarget)).get('attest')==='on'})}><div className="form-grid"><Field label={t('Status','الحالة')}><select name="status" defaultValue={selected.status}>{['planned','in_progress','needs_review','blocked','paused','completed'].map(v=><option key={v} value={v}>{statusText[v][ar?1:0]}</option>)}</select></Field><Field label={t('Owner','المسؤول')}><input name="owner" required defaultValue={selected.owner}/></Field><Field label={t('Next priority','الأولوية القادمة')} wide><textarea name="priority" required defaultValue={selected.priority} maxLength={500}/></Field><Field label={t('Priority level','درجة الأولوية')}><select name="priorityLevel" defaultValue={selected.priorityLevel}>{['high','medium','low'].map(v=><option key={v} value={v}>{statusText[v][ar?1:0]}</option>)}</select></Field><Field label={t('Target date','الموعد المستهدف')}><input type="date" name="due" defaultValue={selected.due}/></Field><Field label={t('Weakness','نقطة الضعف')} wide><textarea name="weakness" defaultValue={selected.weakness} maxLength={2500}/></Field><Field label={t('Blocker','العائق')} wide><textarea name="blocker" defaultValue={selected.blocker} maxLength={2500}/></Field></div><label className="checkbox"><input type="checkbox" name="attest"/><span>{t('For a completed project: I confirm that all scope is represented and every feature has reviewed evidence.','للمشروع المكتمل: أؤكد أن كل النطاق مسجل وأن لكل ميزة دليلًا تمت مراجعته.')}</span></label>{formFooter()}</form>}
 {modal.kind==='weekly'&&<form onSubmit={e=>mutate('weekly',values(e))}><div className="form-grid"><Field label={t('Project','المشروع')}>{projectSelect('projectId',modal.id)}</Field><Field label={t('Week beginning','الأسبوع الذي يبدأ في')}><input name="week" type="date" defaultValue={upcoming()} required/></Field><Field label={t('Progress reported this week','التقدم المبلغ عنه هذا الأسبوع')} wide><textarea name="wins" maxLength={2500} placeholder={t('What changed? Separate claims from verified results.','ما الذي تغير؟ افصل بين الادعاء والنتيجة الموثقة.')}/></Field><Field label={t('Planned work','العمل المخطط')} wide><textarea name="planned" required maxLength={2500}/></Field><Field label={t('Weaknesses','نقاط الضعف')}><textarea name="weakness" maxLength={2500}/></Field><Field label={t('Blockers','العوائق')}><textarea name="blocker" maxLength={2500}/></Field><Field label={t('Decision required (optional)','القرار المطلوب (اختياري)')} wide><textarea name="decision" maxLength={2500}/></Field><Field label={t('One priority for next week','أولوية واحدة للأسبوع القادم')} wide><input name="priority" required maxLength={500}/></Field><Field label={t('Evidence links and notes','روابط الأدلة وملاحظاتها')} wide><textarea name="evidence" maxLength={2500}/></Field></div><div className="note"><ShieldCheck size={16}/><p>{t('Submitting an update never completes a feature. Review each feature’s evidence separately. One update per project and week.','التحديث لا يجعل أي ميزة مكتملة. راجع دليل كل ميزة على حدة. تحديث واحد لكل مشروع وأسبوع.')}</p></div>{formFooter(t('Save weekly update','حفظ التحديث الأسبوعي'))}</form>}
 {modal.kind==='verify'&&selected&&feature&&<FeatureReview feature={feature} ar={ar} saving={saving} onSave={p=>mutate('featureStatus',{...p,projectId:selected.id,featureId:feature.id})} />}
 {modal.kind==='task'&&<form onSubmit={e=>mutate('addTask',values(e))}><div className="form-grid"><Field label={t('Project','المشروع')} wide>{projectSelect()}</Field><Field label={t('Task','المهمة')} wide><input name="title" required maxLength={250}/></Field><Field label={t('Due date','تاريخ الاستحقاق')}><input name="due" type="date" required/></Field><Field label={t('Priority','الأولوية')}><select name="priority">{['high','medium','low'].map(v=><option value={v} key={v}>{statusText[v][ar?1:0]}</option>)}</select></Field></div>{formFooter(t('Add task','إضافة مهمة'))}</form>}
 {modal.kind==='newDecision'&&<form onSubmit={e=>mutate('addDecision',values(e))}><div className="form-grid"><Field label={t('Project','المشروع')} wide>{projectSelect()}</Field><Field label={t('Decision needed','القرار المطلوب')} wide><input name="title" required maxLength={500}/></Field><Field label={t('Context & options','السياق والخيارات')} wide><textarea name="context" required maxLength={2500}/></Field></div>{formFooter(t('Add decision','إضافة قرار'))}</form>}
 {modal.kind==='decision'&&<form onSubmit={e=>mutate('resolveDecision',{...values(e),id:modal.id})}><div className="decision-context"><h3>{state.decisions.find(d=>d.id===modal.id)?.title}</h3><p>{state.decisions.find(d=>d.id===modal.id)?.context}</p></div><Field label={t('Your decision and reasoning','قرارك وأسبابه')}><textarea name="answer" required maxLength={2500} rows={5}/></Field><p className="small-note">{t('Your signed-in name and time will be recorded.','سيُسجل اسم حسابك ووقت اتخاذ القرار.')}</p>{formFooter(t('Record decision','تسجيل القرار'))}</form>}
 {modal.kind==='study'&&(()=>{const s=state.studies.find(x=>x.id===modal.id);return s?<><div className="decision-context"><h3>{s.title}</h3><p>{s.age} · {s.gender} · {s.culture} · {s.language}</p></div><pre className="study-text" dir={s.language==='Arabic'?'rtl':'ltr'}>{s.questions}</pre><div className="form-footer"><button className="btn" onClick={()=>download('ROWAIHY_MIND_questions.txt',s.questions)}><Download size={15}/>{t('Download questions','تنزيل الأسئلة')}</button><button className="btn primary" onClick={()=>{setStudyOptions({projectId:s.projectId,age:s.age,gender:s.gender,culture:s.culture,language:s.language,tone:s.tone});setStudyDraft(s.questions);setResearchTitle(s.title);setPage('research');setModal(null)}}>{t('Open in studio','فتح في الاستوديو')}<ArrowRight size={15}/></button></div></>:null})()}
 </Dialog>}
 </div>
}
function Metric({icon,label,value,note,color}:{icon:ReactNode;label:string;value:number;note:string;color:string}){return <div className="metric"><div><span>{label}</span><span className={'metric-icon '+color}>{icon}</span></div><strong>{String(value).padStart(2,'0')}</strong><p>{note}</p></div>}
function Empty({icon,title,text}:{icon:ReactNode;title:string;text:string}){return <div className="empty"><span>{icon}</span><h3>{title}</h3><p>{text}</p></div>}
function actionLabel(a:string,ar:boolean){const m:Record<string,[string,string]>={createProject:['Project created','تم إنشاء مشروع'],projectUpdate:['Project direction updated','تحديث توجيه المشروع'],addFeature:['Planned feature added','إضافة ميزة مخططة'],featureStatus:['Feature review recorded','تسجيل مراجعة ميزة'],weekly:['Weekly update saved','حفظ التحديث الأسبوعي'],addTask:['Task added','إضافة مهمة'],taskStatus:['Task status changed','تغيير حالة مهمة'],addDecision:['Decision requested','طلب قرار'],resolveDecision:['Founder decision recorded','تسجيل قرار المؤسس'],saveStudy:['Research draft saved','حفظ مسودة بحث']};return m[a]?.[ar?1:0]??a}
function FeatureReview({feature,ar,saving,onSave}:{feature:Feature;ar:boolean;saving:boolean;onSave:(p:Record<string,unknown>)=>void}){const [status,setStatus]=useState(feature.status);const t=(e:string,a:string)=>ar?a:e;return <form onSubmit={e=>{const v=values(e);onSave({...v,attest:v.attest==='on'})}}><div className="decision-context"><h3>{feature.title}</h3><p>{t('The reviewer is responsible for checking that the evidence demonstrates this exact feature.','المراجع مسؤول عن التأكد من أن الدليل يثبت هذه الميزة تحديدًا.')}</p></div><Field label={t('Feature status','حالة الميزة')}><select name="status" value={status} onChange={e=>setStatus(e.target.value as Feature['status'])}>{['planned','in_progress','blocked','in_review','completed'].map(v=><option key={v} value={v}>{statusText[v][ar?1:0]}</option>)}</select></Field>{status==='completed'&&<div className="form-grid proof-form"><Field label={t('Evidence URL (HTTPS)','رابط الدليل (HTTPS)')} wide><input type="url" name="url" required pattern="https://.*" placeholder="https://…" defaultValue={feature.evidence?.url}/></Field><Field label={t('Evidence type','نوع الدليل')} wide><select name="kind" defaultValue={feature.evidence?.kind}>{['Test report','Deployed flow','Pull request','Design review','Document'].map(k=><option key={k}>{k}</option>)}</select></Field><Field label={t('What does this evidence demonstrate?','ما الذي يثبته الدليل؟')} wide><textarea name="summary" required maxLength={1500} defaultValue={feature.evidence?.summary}/></Field><Field label={t('Test steps and observed outcome','خطوات التحقق والنتيجة الملحوظة')} wide><textarea name="result" required maxLength={1500} defaultValue={feature.evidence?.result}/></Field><label className="checkbox wide"><input type="checkbox" name="attest" required/><span>{t('I opened the evidence and verified this feature against its acceptance criteria. This is a human review, not automatic validation.','فتحت الدليل وتحققت من الميزة وفق معايير قبولها. هذه مراجعة بشرية وليست تحققًا آليًا.')}</span></label></div>}{feature.evidence&&status!=='completed'&&<p className="warning">{t('Reopening removes the active completion evidence. The prior change remains in the activity history.','إعادة فتح الميزة تلغي اعتماد دليل الاكتمال الحالي. يبقى التغيير السابق في سجل النشاط.')}</p>}<div className="form-footer"><button className="btn primary" disabled={saving}><ShieldCheck size={16}/>{t('Save review','حفظ المراجعة')}</button></div></form>}
